package mx.gob.sedesol.basegestor.gestionescolar.v2;

import static org.testng.Assert.assertEquals;
import static org.testng.Assert.assertFalse;
import static org.testng.Assert.assertTrue;

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;

import org.testng.annotations.Test;

import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaIndisponibilidadOfertaV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaPendienteUnidadV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CodigoReglaCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ContextoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EstadoUnidadCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EvaluacionCargaAcademicaV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ResultadoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.UnidadEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;

/** F4D-U-01 a F4D-U-25: RN-5.2 compone resultados severos sin duplicar RN-6.4. */
public class EvaluacionCurricularV2Fase4DTest {
    private final EvaluacionCurricularV2ServiceImpl service=new EvaluacionCurricularV2ServiceImpl();
    @Test public void f4DU01CeroNoAplica(){assertFalse(e(c(obligatoria(1L))).getEvaluacionCargaAcademica().getAplicaRn52());}
    @Test public void f4DU02UnaUsaRn51NoRn52(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobada(10L))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertFalse(x.getAplicaRn52());}
    @Test public void f4DU03TresUsaLeveNoSevero(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(20L,3))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertFalse(x.getAplicaRn52());assertEquals(x.getCondicionRegularizacion(),"REZAGO_LEVE");}
    @Test public void f4DU04CuatroComponeSeveroConRn64(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(30L,4))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn52());assertTrue(x.getAplicaRn64());assertEquals(x.getCondicionRegularizacion(),"REZAGO_SEVERO");}
    @Test public void f4DU05CincoComponeSevero(){assertTrue(e(c(reprobadas(40L,5))).getEvaluacionCargaAcademica().getAplicaRn52());}
    @Test public void f4DU06InconsistenciaRn64RequiereRevision() throws Exception {ContextoEvaluacionCurricularV2DTO z=c(reprobadas(50L,4));ResultadoEvaluacionCurricularV2DTO r=e(z);EvaluacionCargaAcademicaV2DTO x=r.getEvaluacionCargaAcademica();x.setAplicaRn64(Boolean.FALSE);x.setRequiereRevision(Boolean.FALSE);Method m=EvaluacionCurricularV2ServiceImpl.class.getDeclaredMethod("evaluarCargaRezagoSevero",ResultadoEvaluacionCurricularV2DTO.class,ContextoEvaluacionCurricularV2DTO.class);m.setAccessible(true);m.invoke(service,r,z);assertTrue(x.getAplicaRn52());assertTrue(x.getRequiereRevision());}
    @Test public void f4DU07ConsumeBloqueoObligatoriaNueva(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(60L,4));z.getUnidades().add(obligatoria(64L));EvaluacionCargaAcademicaV2DTO x=e(z).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn52());assertTrue(x.getUdsObligatoriasNuevasBloqueadasRn64().contains(Long.valueOf(64L)));}
    @Test public void f4DU08ConsumeOptativaRn64(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(70L,4));z.getUnidades().add(optativa(74L));EvaluacionCargaAcademicaV2DTO x=e(z).getEvaluacionCargaAcademica();assertTrue(x.getUdsOptativasAdicionalesElegiblesRn64().contains(Long.valueOf(74L)));}
    @Test public void f4DU09DosOfertadasMantieneSeveroYExcepcion(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(80L,4);us.get(2).setOfertada(Boolean.FALSE);us.get(3).setOfertada(Boolean.FALSE);EvaluacionCargaAcademicaV2DTO x=e(c(us)).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn52());assertTrue(x.getExcepcionMinimoAplicable());}
    @Test public void f4DU10SinOfertaSigueContando(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(90L,4);us.get(3).setOfertada(Boolean.FALSE);us.get(3).setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO);ResultadoEvaluacionCurricularV2DTO r=e(c(us));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertTrue(r.getEvaluacionCargaAcademica().getAplicaRn52());}
    @Test public void f4DU11SinCupoSeDistingue(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(100L,4);us.get(3).setCupoDisponibleConocido(Boolean.FALSE);us.get(3).setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.SIN_CUPO);assertTrue(e(c(us)).getEvaluacionCargaAcademica().getCausasIndisponibilidadRegularizacion().toString().contains("SIN_CUPO"));}
    @Test public void f4DU12CargaMayorASeisConservaMaximo(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(110L,4));z.getUnidades().addAll(reprobadas(114L,3));EvaluacionCargaAcademicaV2DTO x=e(z).getEvaluacionCargaAcademica();assertEquals(x.getCargaMaximaNormativa(),Integer.valueOf(6));assertFalse(x.getMaximoCumplido());}
    @Test public void f4DU13QuintoMantienePrevalenciaRn64(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(120L,4));z.setSemestreObjetivo(Integer.valueOf(5));z.setPeriodoNormativo("2027-1");z.setAvanceCondicionado(Boolean.TRUE);ResultadoEvaluacionCurricularV2DTO r=e(z);assertTrue(r.getEvaluacionCargaAcademica().getCtr01Rn61Procedente());assertTrue(r.getEvaluacionCargaAcademica().getAvanceCondicionadoBloqueadoPorRn64());}
    @Test public void f4DU14TerceroNoTieneCtr01(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(130L,4));z.setPeriodoNormativo("2027-1");assertFalse(e(z).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4DU15SeptimoNoTieneCtr01(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(140L,4));z.setSemestreObjetivo(Integer.valueOf(7));z.setPeriodoNormativo("2027-1");assertFalse(e(z).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4DU16CincoACuatroSigueSevero(){assertTrue(e(c(reprobadas(150L,4))).getEvaluacionCargaAcademica().getAplicaRn52());}
    @Test public void f4DU17CuatroATresPasaALeve(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(160L,3))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn52());assertFalse(x.getAplicaRn64());assertTrue(x.getAplicaRn51());}
    @Test public void f4DU18CuatroACeroNoHaceCambioDirectoDeRn52(){EvaluacionCargaAcademicaV2DTO x=e(c(acreditada(170L),acreditada(171L),acreditada(172L),acreditada(173L))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn52());assertFalse(x.getAplicaRn64());}
    @Test public void f4DU19IntentosNoSonUds(){UnidadEvaluacionCurricularV2DTO u=reprobada(180L);u.setIntentosFallidosHistoricosConfiables(Integer.valueOf(3));ResultadoEvaluacionCurricularV2DTO r=e(c(u,reprobada(181L),reprobada(182L),reprobada(183L)));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertTrue(r.getEvaluacionCargaAcademica().getAplicaRn52());}
    @Test public void f4DU20BajaParcialNoSuma(){UnidadEvaluacionCurricularV2DTO b=obligatoria(195L);b.setEstado(EstadoUnidadCurricularV2.BAJA_PARCIAL);b.setCausa(CausaPendienteUnidadV2.BAJA_PARCIAL);List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(190L,4);us.add(b);assertEquals(e(c(us)).getCantidadReprobadasVigentes(),Integer.valueOf(4));}
    @Test public void f4DU21NoCursadaNoSuma(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(200L,4);us.add(obligatoria(204L));ResultadoEvaluacionCurricularV2DTO r=e(c(us));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));}
    @Test public void f4DU22DuplicadoNoDuplica(){UnidadEvaluacionCurricularV2DTO a=reprobada(210L),b=reprobada(210L);a.setBloque("B1");b.setBloque("B2");assertEquals(e(c(a,b,reprobada(211L),reprobada(212L),reprobada(213L))).getCantidadReprobadasVigentes(),Integer.valueOf(4));}
    @Test public void f4DU23NoDeterminadoRequiereRevision(){EvaluacionCargaAcademicaV2DTO x=e(c(indeterminada(220L))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn52());assertTrue(x.getRequiereRevision());}
    @Test public void f4DU24MismoContextoEsDeterminista(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(230L,4));assertEquals(e(z).getEvaluacionCargaAcademica().getAplicaRn52(),e(z).getEvaluacionCargaAcademica().getAplicaRn52());}
    @Test public void f4DU25NoTieneEfectoProductivo(){UnidadEvaluacionCurricularV2DTO u=reprobada(240L);ResultadoEvaluacionCurricularV2DTO r=e(c(u,reprobada(241L),reprobada(242L),reprobada(243L)));assertFalse(r.getEfectosProductivosAplicados());assertTrue(u.getOfertada());assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_5_2));}
    private ResultadoEvaluacionCurricularV2DTO e(ContextoEvaluacionCurricularV2DTO z){return service.evaluarSombra(z);} private ContextoEvaluacionCurricularV2DTO c(UnidadEvaluacionCurricularV2DTO...us){ContextoEvaluacionCurricularV2DTO z=new ContextoEvaluacionCurricularV2DTO();z.setVersionReglas("PE2027-V1");z.setFechaEvaluacion(new Date(0L));z.setSemestreObjetivo(Integer.valueOf(3));z.setActividadAcademicaComprobada(Boolean.TRUE);z.setPermanenciaDentroLimiteComprobada(Boolean.TRUE);z.setDictaminacionEgresoConocida(Boolean.TRUE);z.setOportunidadesMejoraUtilizadas(Integer.valueOf(0));for(UnidadEvaluacionCurricularV2DTO u:us)z.getUnidades().add(u);return z;} private ContextoEvaluacionCurricularV2DTO c(List<UnidadEvaluacionCurricularV2DTO> us){return c(us.toArray(new UnidadEvaluacionCurricularV2DTO[us.size()]));}
    private List<UnidadEvaluacionCurricularV2DTO> reprobadas(Long i,int n){List<UnidadEvaluacionCurricularV2DTO> r=new ArrayList<UnidadEvaluacionCurricularV2DTO>();for(int x=0;x<n;x++)r.add(reprobada(Long.valueOf(i.longValue()+x)));return r;} private UnidadEvaluacionCurricularV2DTO obligatoria(Long i){return pendiente(i,"Obligatoria");} private UnidadEvaluacionCurricularV2DTO optativa(Long i){return pendiente(i,"Optativa");} private UnidadEvaluacionCurricularV2DTO reprobada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.REPROBADA);u.setCausa(CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(Boolean.TRUE);u.setReprobacionPeriodoPrevioConocida(Boolean.TRUE);return u;} private UnidadEvaluacionCurricularV2DTO acreditada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.ACREDITADA);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO indeterminada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.NO_DETERMINADO);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO pendiente(Long i,String t){UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(i);u.setClave("UD"+i);u.setTipoUd(t);u.setEstado(EstadoUnidadCurricularV2.NO_CURSADA);u.setCausa(CausaPendienteUnidadV2.NO_CURSAMIENTO);u.setOfertada(Boolean.TRUE);u.setGrupoActivoConocido(Boolean.TRUE);u.setCupoDisponibleConocido(Boolean.TRUE);u.setSeleccionableOrigen(Boolean.TRUE);return u;}
}
